<br><section class="panel"><div class="panel-head"><div><h2>Sales Report</h2><span class="panel-sub">Complete sales transaction history</span></div></div><div class="table-wrap"><table class="table"><tr><th>Date</th><th>Customer</th><th>Product</th><th>SKU</th><th>Qty</th><th>Selling Price</th><th>Cost Price</th><th>Profit / Loss</th><th>Total</th><th>Status</th></tr><?php foreach($rows as $r): ?><tr><td><?=e(date('d M Y, h:i A',strtotime($r['created_at'])))?></td><td><?=e($r['customer']??'Walk-in')?></td><td><b><?=e($r['product'])?></b></td><td><?=e($r['sku'])?></td><td><?=e($r['quantity'])?></td><td>৳<?=number_format((float)$r['unit_price'],2)?></td><td>৳<?=number_format((float)$r['cost_price'],2)?></td><td><?php $m=((float)$r['unit_price']-(float)$r['cost_price'])*(int)$r['quantity']; ?><span class="badge <?=$m>=0?'green':'red'?>"><?=$m>=0?'Profit: ':'Loss: '?>৳<?=number_format(abs($m),2)?></span></td><td>৳<?=number_format((float)$r['total'],2)?></td><td><span class="badge <?=$r['status']==='Completed'?'green':'gray'?>"><?=e($r['status'])?></span></td></tr><?php endforeach; ?><?php if(!$rows): ?><tr><td colspan="10" class="empty">No sales records available.</td></tr><?php endif; ?></table></div></section><?php require __DIR__.'/../../../includes/role_footer.php'; ?>
